    $stockLabels = ['ON_HAND' => 'In stock', 'RESERVED' => 'Reserved', 'IN_TRANSFER' => 'In transfer', 'NONE' => 'Not in stock'];
    $filterUrl = function (array $change = []) use ($filters, $query, $locationId) { return route('recommerce.devices.index', array_filter(array_merge(['location_id' => $locationId, 'q' => $query], $filters, $change), fn ($value) => $value !== '' && $value !== 0 && $value !== false && $value !== null)); };
    $quickFilterUrl = function (array $change = []) use ($filters, $locationId) { return route('recommerce.devices.index', array_filter(array_merge(['location_id' => $locationId], $filters, ['state' => '', 'custody' => '', 'transfer_state' => ''], $change), fn ($value) => $value !== '' && $value !== 0 && $value !== false && $value !== null)); };
