elStatus }}</small></td><td>{{ optional($device->product)->name ?: 'Product unavailable' }}@if(optional($device->variation)->name)<br><small class="text-muted">{{ $device->variation->name }}</small>@endif</td><td class="sb-registry-hide-mobile">{{ $device->manufacturer_serial_display ? 'Serial ending '.substr($device->manufacturer_serial_display, -4) : 'Not recorded' }}</td><td><span class="sb-state-badge">{{ $lifecycleLabels[$device->lifecycle_state] ?? ucwords(strtolower(str_replace('_', ' ', $device->lifecycle_state))) }}</span>@if(($device->transfer_state ?? 'NONE') !== 'NONE')<br><small class="text-warning">{{ ucwords(strtolower(str_replace('_', ' ', $device->transfer_state))) }}</small>@endif</td><td>{{ $holder }}<br><small class="text-muted">{{ $stockLabels[$device->stock_participation] ?? $device->stock_participation }}</small></td><td class="sb-registry-age sb-registry-hide-mobile">{{ $device->acquired_at ? $device->acquired_at->diffForHumans(null, true) : '—' }}</td><td class="sb-registry-actions"><button class="btn btn-default btn-xs" type="button" data-quick-view>Quick view</button>@if($canPrintDevice && ! empty($device->id)) <form method="post" action="{{ route('recommerce.devices.label.print', $device->id) }}" data-recommerce-label-print style="display:inline-block;margin-left:4px">@csrf<button class="btn btn-primary btn-xs" type="button"><i class="fa fa-print"></i><span class="sr-only"> Print label</span></button></form>@endif</td></tr>@empty <tr><td colspan="{{ ($canPrintLabel ?? false) ? 8 : 7 }}" class="text-muted">@if($query !== '') No device matches “{{ $query }}”. Try another identifier or clear filters. @elseif($activeChips->isNotEmpty()) No Devices match these filters. <a href="{{ route('recommerce.devices.index', ['location_id' => $locationId]) }}">Clear filters</a>. @else No tracked Devices have been registered yet. Start from Purchases to receive supplier stock. @endif</td></tr>@endforelse</tbody></table></div>
