<script>(function(){const drawer=document.getElementById('registry-quick-view'),content=drawer&&drawer.querySelector('[data-registry-quick-view-content]');if(!drawer||!content)return;const close=()=>{drawer.classList.remove('is-open');drawer.setAttribute('aria-hidden','true')};document.addEventListener('click',async event=>{const trigger=event.target.closest('[data-quick-view]');if(!trigger){if(event.target.closest('[data-registry-close]'))close();return}event.preventDefault();const row=trigger.closest('[data-quick-view-url]');if(!row)return;content.innerHTML='<p class="text-muted">Loading Device…</p>';drawer.classList.add('is-open');drawer.setAttribute('aria-hidden','false');try{const response=await fetch(row.dataset.quickViewUrl,{headers:{'X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw new Error();content.innerHTML=await response.text();const closeButton=content.querySelector('[data-registry-close]');if(closeButton)closeButton.focus()}catch(error){content.innerHTML='<p class="text-danger">Unable to open this Device. Open the full record to continue.</p>'}});document.addEventListener('keydown',event=>{if(event.key==='Escape')close()})}())</script>
<script>(function(){const form=document.getElementById('recommerce-bulk-label-print');if(!form)return;const all=document.querySelector('[data-registry-select-visible]'),count=form.querySelector('[data-registry-selection-count]'),clear=form.querySelector('[data-registry-clear-selection]'),boxes=()=>Array.from(document.querySelectorAll('[data-registry-selection]'));const update=()=>{const selected=boxes().filter(box=>box.checked);form.hidden=selected.length===0;if(count)count.textContent=`${selected.length} ${selected.length===1?'device':'devices'} selected`;if(all){const available=boxes();all.checked=available.length>0&&selected.length===available.length;all.indeterminate=selected.length>0&&selected.length<available.length}document.querySelectorAll('.sb-registry-row').forEach(row=>row.classList.toggle('is-selected',Boolean(row.querySelector('[data-registry-selection]:checked'))))};document.addEventListener('change',event=>{if(event.target.matches('[data-registry-selection]'))update()});if(all)all.addEventListener('change',()=>{boxes().forEach(box=>{box.checked=all.checked});update()});if(clear)clear.addEventListener('click',()=>{boxes().forEach(box=>{box.checked=false});update()});update()}())</script>
